import{_ as a,o as t,c as r,a5 as o}from"./chunks/framework.BrSBneze.js";const b=JSON.parse('{"title":"Assemble and mount","description":"","frontmatter":{},"headers":[],"relativePath":"hardware/assembly.md","filePath":"hardware/assembly.md","lastUpdated":1788882780000}'),i={name:"hardware/assembly.md"};function n(s,e,l,h,d,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="assemble-and-mount" tabindex="-1">Assemble and mount <a class="header-anchor" href="#assemble-and-mount" aria-label="Permalink to &quot;Assemble and mount&quot;">​</a></h1><p>Check that each mechanism moves through its full range and remains seated during manipulation.</p><h2 id="before-assembly" tabindex="-1">Before assembly <a class="header-anchor" href="#before-assembly" aria-label="Permalink to &quot;Before assembly&quot;">​</a></h2><p>Inspect all printed parts for:</p><ul><li>warped mounting faces;</li><li>incomplete threads;</li><li>support material inside holes or tracks;</li><li>cracks around thin mechanisms; and</li><li>loose press-fit interfaces.</li></ul><p>Replace damaged functional parts rather than forcing them into place.</p><h2 id="assemble-the-base" tabindex="-1">Assemble the base <a class="header-anchor" href="#assemble-the-base" aria-label="Permalink to &quot;Assemble the base&quot;">​</a></h2><ol><li>Place the honeycomb base on a flat surface.</li><li>Check that all seven cells are clear and dimensionally consistent.</li><li>Insert one attachment base and press evenly until it is fully seated.</li><li>Remove and reinsert the test attachment to confirm repeatable fit.</li><li>Repeat the seating check across the cells you intend to use.</li></ol><h2 id="assemble-the-mechanisms" tabindex="-1">Assemble the mechanisms <a class="header-anchor" href="#assemble-the-mechanisms" aria-label="Permalink to &quot;Assemble the mechanisms&quot;">​</a></h2><p>The repository groups all parts required by each attachment in a dedicated STL folder. Keep the printed components from each folder together during assembly.</p><h3 id="threaded-parts" tabindex="-1">Threaded parts <a class="header-anchor" href="#threaded-parts" aria-label="Permalink to &quot;Threaded parts&quot;">​</a></h3><p>Engage the part by hand without axial forcing. It should advance smoothly while remaining constrained by the thread. If it binds, remove debris and test the matching calibration piece before sanding the final component.</p><h3 id="ball-valve-and-friction-rings" tabindex="-1">Ball valve and friction rings <a class="header-anchor" href="#ball-valve-and-friction-rings" aria-label="Permalink to &quot;Ball valve and friction rings&quot;">​</a></h3><p>Assemble the ball valve without a ring first. The ring configuration is evaluated as a separate attachment and should only be fitted for the corresponding trial block.</p><h3 id="covered-button" tabindex="-1">Covered button <a class="header-anchor" href="#covered-button" aria-label="Permalink to &quot;Covered button&quot;">​</a></h3><p>Confirm that the cover opens freely and that the button returns after it is pressed. Both stages must remain visually distinguishable.</p><h3 id="drawer" tabindex="-1">Drawer <a class="header-anchor" href="#drawer" aria-label="Permalink to &quot;Drawer&quot;">​</a></h3><p>Check the full pull-and-push travel. The drawer must not disengage unintentionally from its base during normal use.</p><h3 id="lock-and-key" tabindex="-1">Lock and key <a class="header-anchor" href="#lock-and-key" aria-label="Permalink to &quot;Lock and key&quot;">​</a></h3><p>Check insertion and rotation manually. The initial key position must be repeatable across trials.</p><h3 id="shock-absorber" tabindex="-1">Shock absorber <a class="header-anchor" href="#shock-absorber" aria-label="Permalink to &quot;Shock absorber&quot;">​</a></h3><p>Confirm that the pin can be grasped, aligned, and fully inserted. This attachment occupies two adjacent cells; reserve both before arranging the board.</p><h2 id="mount-the-board" tabindex="-1">Mount the board <a class="header-anchor" href="#mount-the-board" aria-label="Permalink to &quot;Mount the board&quot;">​</a></h2><p>Fix the base to a rigid surface within the platform&#39;s working volume. Horizontal tabletop and vertical fixture mounting are both allowed, but the orientation must be reported because it changes the approach direction and the likelihood of an attachment releasing from its cell.</p><p>Before recorded trials:</p><ol><li>fully seat every attachment;</li><li>confirm that all modules are reachable without moving the base during a trial;</li><li>check for collision risks around the fixture;</li><li>photograph the setup as <code>setup.jpg</code>; and</li><li>describe the mounting orientation in <code>platform.md</code>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Dynamic loading</p><p>High-gain or jittering commands can damage printed mechanisms or loosen press-fit attachments. Inspect the board before every session and after any contact that visibly displaces a module.</p></div><p>Continue with the <a href="/hiveboard-docs/benchmark/protocol">evaluation protocol</a>.</p>',28)])])}const u=a(i,[["render",n]]);export{b as __pageData,u as default};
